function boothBookings(gap, operations) {
  const HORIZON = 1000000;
  const owner = new Int32Array(HORIZON + 1);
  const isStart = new Uint8Array(HORIZON + 1);
  const spans = new Map();
  let issued = 0;
  const results = [];
  for (const op of operations) {
    if (op[0] === "book") {
      const start = op[1];
      const end = op[2];
      let clash = false;
      const from = Math.max(0, start - gap);
      const to = Math.min(HORIZON, end + gap);
      for (let minute = from; minute < to && !clash; minute++) {
        if (owner[minute] !== 0) clash = true;
      }
      if (clash) {
        results.push(-1);
      } else {
        issued++;
        for (let minute = start; minute < end; minute++) owner[minute] = issued;
        isStart[start] = 1;
        spans.set(issued, [start, end]);
        results.push(issued);
      }
    } else if (op[0] === "cancel") {
      const span = spans.get(op[1]);
      if (span === undefined) {
        results.push(false);
      } else {
        for (let minute = span[0]; minute < span[1]; minute++) owner[minute] = 0;
        isStart[span[0]] = 0;
        spans.delete(op[1]);
        results.push(true);
      }
    } else {
      let minute = op[1];
      while (minute <= HORIZON && isStart[minute] === 0) minute++;
      results.push(minute > HORIZON ? -1 : minute);
    }
  }
  return results;
}

function boothBookings(gap, operations) {
  const starts = [];
  const ends = [];
  const startOfId = new Map();
  let issued = 0;
  const firstAtLeast = (time) => {
    let low = 0;
    let high = starts.length;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (starts[mid] < time) low = mid + 1;
      else high = mid;
    }
    return low;
  };
  const results = [];
  for (const op of operations) {
    if (op[0] === "book") {
      const start = op[1];
      const end = op[2];
      const at = firstAtLeast(start);
      const clearBefore = at === 0 || ends[at - 1] + gap <= start;
      const clearAfter = at === starts.length || end + gap <= starts[at];
      if (clearBefore && clearAfter) {
        starts.splice(at, 0, start);
        ends.splice(at, 0, end);
        issued++;
        startOfId.set(issued, start);
        results.push(issued);
      } else {
        results.push(-1);
      }
    } else if (op[0] === "cancel") {
      const start = startOfId.get(op[1]);
      if (start === undefined) {
        results.push(false);
      } else {
        const at = firstAtLeast(start);
        starts.splice(at, 1);
        ends.splice(at, 1);
        startOfId.delete(op[1]);
        results.push(true);
      }
    } else {
      const at = firstAtLeast(op[1]);
      results.push(at === starts.length ? -1 : starts[at]);
    }
  }
  return results;
}
